    black_shawl_patches = [s for s in shawl_patches if s.best_text_match(["black"])]
    woman_patches = image_patch.find("woman")
    if not woman_patches: return image_patch

    for woman in woman_patches:
        for blanket in black_blanket_patches:
            if woman.overlaps_with(blanket.left, blanket.lower, blanket.right, blanket.upper):
                return woman
        for shawl in black_shawl_patches:
            if woman.overlaps_with(shawl.left, shawl.lower, shawl.right, shawl.upper):
                return woman
    return woman_patches[0]

