def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    gray_hoodie_patches = image_patch.find("gray hoodie")

    if not man_patches or not gray_hoodie_patches:
        return image_patch

    # Assuming the man with the gray hoodie is the one closest to the camera
    man_with_hoodie = None
    min_depth = float('inf')

    for man in man_patches:
        for hoodie in gray_hoodie_patches:
            if man.overlaps_with(hoodie.left, hoodie.lower, hoodie.right, hoodie.upper):
                current_depth = man.compute_depth()
                if current_depth < min_depth:
                    min_depth = current_depth
                    man_with_hoodie = man

    return man_with_hoodie if man_with_hoodie else image_patch

